"""Figure for the reactive-pair mechanism study -> reports/figures/bl_mech_logic.png"""
import sys, os, warnings; sys.path.insert(0, '.'); warnings.filterwarnings('ignore')
import numpy as np, pandas as pd, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
from bl_common import OUT
FIG = os.path.join(os.path.dirname(OUT), 'reports', 'figures'); os.makedirs(FIG, exist_ok=True)
Hb = pd.read_csv(f'{OUT}/bl_mech_hazard_block.csv'); P = pd.read_csv(f'{OUT}/bl_mech_panel.csv.gz'); T = pd.read_csv(f'{OUT}/bl_mech_strike_rules.csv', index_col=0); C = pd.read_csv(f'{OUT}/bl_mech_census.csv', index_col=0)
fig, ax = plt.subplots(2, 2, figsize=(13.5, 9.5))
a = ax[0, 0]; x = np.arange(len(Hb)); a.bar(x, Hb.R_per1000, color='#ff7f0e', label='reactive pairs per 1000 cycle-minutes'); a.axvspan(5 - .5, 23 + .5, color='#ff7f0e', alpha=.08); a.set_xticks(x[::2]); a.set_xticklabels(Hb.clock[::2], rotation=60, fontsize=7); a.set_ylabel('reactive-pair hazard (per 1000 cycle-minutes)')
b = a.twinx(); b.plot(x, Hb.tot_vol_med / 1e6, 'k-o', ms=3, label='median option volume per 15 min (millions)'); b.set_ylabel('option volume (millions)'); a.set_title('A. Reactive pairs switch on at 10:30 — volume does not'); a.axvline(13 - .5, color='b', ls=':', lw=1); a.text(13 - .4, a.get_ylim()[1] * .9, 'London 12:30', fontsize=7, color='b'); h1, l1 = a.get_legend_handles_labels(); h2, l2 = b.get_legend_handles_labels(); a.legend(h1 + h2, l1 + l2, fontsize=7, loc='upper left')
a = ax[0, 1]; y = P.yR.values; j = P.j.values
def ll(t0, t1=360, eps=1e-4):
    inw = (j >= t0) & (j < t1); n1 = inw.sum(); e1 = y[inw].sum(); h = max(e1 / n1, eps); n0 = (~inw).sum(); e0 = y[~inw].sum(); h0 = max(e0 / max(n0, 1), eps); return e1 * np.log(h) + (n1 - e1) * np.log(1 - h) + e0 * np.log(h0) + (n0 - e0) * np.log(1 - h0)
ts = np.arange(10, 150, 5); pr = np.array([ll(t) for t in ts]); pr -= pr.max(); a.plot([f'{(9 * 60 + 15 + t) // 60}:{(9 * 60 + 15 + t) % 60:02d}' for t in ts], pr, 'o-', color='#d62728'); a.set_xticks(range(0, len(ts), 3)); a.tick_params(axis='x', rotation=60, labelsize=7); a.set_ylabel('log-likelihood minus maximum'); a.set_xlabel('assumed start of the active window'); a.set_title('B. The start is sharp: 10:30 (stop 15:15)')
a = ax[1, 0]; Tt = T.drop(index=['previous reactive strike +-1 step', 'strike of previous reactive pair'], errors='ignore').sort_values('reactive_hit', ascending=False).head(7); lab = [i.replace('nearest(', 'nearest(').replace('floor/ceil of spot toward', 'floor/ceil toward') for i in Tt.index]; yy = np.arange(len(Tt)); a.barh(yy - .2, Tt.reactive_hit * 100, .4, color='#ff7f0e', label='reactive pairs'); a.barh(yy + .2, Tt.timetable_hit * 100, .4, color='#2ca02c', label='timetable pairs'); a.set_yticks(yy); a.set_yticklabels(lab, fontsize=7); a.invert_yaxis(); a.set_xlabel('% of pairs whose strike equals the rule'); a.axvline(80, color='k', ls=':', lw=1); a.set_title('C. Strike rule: ATM + 1 step toward the recent move (79%)'); a.legend(fontsize=7)
a = ax[1, 1]; Cc = C.sort_values('lots_per_cycle'); cols = {'scheduled cell': '#2ca02c', 'reactive pair (outside timetable)': '#ff7f0e'}; a.barh(range(len(Cc)), Cc.lots_per_cycle, color=[cols.get(i, '#9467bd' if ('solo' in i or 'batch' in i or 'near' in i) else '#8c564b') for i in Cc.index]); a.set_yticks(range(len(Cc))); a.set_yticklabels([i.replace(' (outside timetable)', '').replace(' (>= 3 lots, one strike/right, within 3 s)', ' (>=3 lots)').replace(' (CE and PE within 3 s, different strikes)', '') for i in Cc.index], fontsize=7); a.set_xlabel('D-1 sold lots per cycle'); a.set_title('D. Census of all D-1 sells (6,072 lots)')
fig.suptitle('Algo 8 D-1 reactive pairs: gate, strike rule and the census of all sells — in-sample, 32 cycles', fontsize=11); fig.tight_layout(); fig.savefig(f'{FIG}/bl_mech_logic.png', dpi=140); print('saved')
